PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investor) AS ?count)
WHERE {
  ?scenarioRebalancing ex:hasInvestor ?investor .
  ?portfolioHealth ex:hasInvestor ?investor .
  ?scenarioRebalancing ex:scenario "Interest Rate Hike" .
  ?portfolioHealth ex:diversificationScore "Moderate" .
  FILTER NOT EXISTS { 
    ?otherScenarioRebalancing ex:hasInvestor ?investor .
    ?otherScenarioRebalancing ex:scenario "Interest Rate Hike" .
    MINUS {
      ?otherScenarioRebalancing ex:rationale ?reason .
      FILTER(LCASE(STR(?reason)) = "interest rate hike")
    }
  }
}

