PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (xsd:decimal(SUM(xsd:decimal(?holdingDuration))) AS ?avgHoldingDuration)
WHERE {
  BIND((xsd:date() - xsd:date(?purchaseDate)) AS ?holdingDuration)
  ?investmentGoal ex:hasInvestor ?investor .
  ?portfolioHolding ex:hasInvestor ?investor .
  FILTER(LCASE(STR(?investmentGoal)) = LCASE(STR(?portfolioHolding)))
  BIND(?investmentGoal AS ?goal)
  BIND(?portfolioHolding AS ?holding)
  OPTIONAL { ?goal schema1:description ?description }
  OPTIONAL { ?holding ex:purchaseDate ?purchaseDate }
  FILTER NOT EXISTS {
    ?goal ex:hasInvestor ?otherInvestor .
    FILTER(LCASE(STR(?otherInvestor)) != LCASE(STR(?investor)))
  }
}
GROUP BY ?investor

