SELECT ?year (SUM(xsd:decimal(?totalInvestment)) AS ?totalAmount)
WHERE {
  VALUES (?year) {(2022) (2023) (2024)}
  ?sectorAllocation ex:hasSector ?sector .
  ?sector a schema1:Sector .
  ?sectorAllocation ex:totalInvestment ?totalInvestment .

  UNION {
    VALUES (?year) {(2022) (2023) (2024)}
    ?investmentGoal ex:hasInvestor ?investor .
    ?investmentGoal a schema1:InvestmentGoal .
    ?investmentGoal ex:targetAmount ?totalInvestment .
  }
}
GROUP BY ?year
ORDER BY DESC(?totalAmount)
LIMIT 1

