SELECT ?investor (SUM(xsd:decimal(?value)) AS ?totalLumpSum)
WHERE {
  ?investmentGoal ex:hasInvestor ?investor .
  ?portfolioHolding ex:hasInvestor ?investor .
  ?portfolioHolding ex:currentValue ?value .
  FILTER (?value > 0) .
  OPTIONAL { 
    ?investmentGoal schema1:targetAmount ?targetAmount .
    FILTER ((xsd:decimal(?targetAmount) = xsd:decimal(?value)) OR (xsd:decimal(?targetAmount) < xsd:decimal(?value)))
  }
  OPTIONAL {
    ?portfolioHolding ex:cost ?cost .
    FILTER ((xsd:decimal(?cost) = xsd:decimal(?value)) OR (xsd:decimal(?cost) < xsd:decimal(?value)))
  }
}
GROUP BY ?investor

